import{_ as g,C as E,o as a,c as u,j as o,a as e,b as i,w as r,E as s,a3 as d,a2 as n}from"./chunks/framework.l6sz0Vgx.js";const m=JSON.parse('{"title":"存储笔记","description":"MySQL / Redis / MQ 在请求链路中的分工与可靠性","frontmatter":{"title":"存储笔记","description":"MySQL / Redis / MQ 在请求链路中的分工与可靠性"},"headers":[],"relativePath":"posts/storage.md","filePath":"posts/storage.md","lastUpdated":1791726807000}'),c={name:"posts/storage.md"};function A(h,t,B,b,L,_){const l=E("Mermaid");return a(),u("div",null,[t[3]||(t[3]=o("h1",{id:"存储笔记",tabindex:"-1"},[e("存储笔记 "),o("a",{class:"header-anchor",href:"#存储笔记","aria-label":'Permalink to "存储笔记"'},"​")],-1)),t[4]||(t[4]=o("p",null,[o("strong",null,"摘要："),e(' 落库 MySQL 管可靠、热数据 Redis 管快、MQ 管异步解耦——三者在请求链路中分工不同。本篇按"链路位置 → 单件原理 → 可靠性三问 → 三件套对照"组织，缓存双写与事务消息等联动点收在§4。')],-1)),t[5]||(t[5]=o("p",null,[o("strong",null,"怎么读："),e(' §1 MySQL（索引与事务）→ §2 Redis（数据结构 → 系统架构 → 应用）→ §3 MQ（异步与可靠性）→ §4 联动（双写一致性 + 可靠投递）→ §5 三件套事务一致性对照。标"常问"的是高频口述点。')],-1)),(a(),i(d,null,{default:r(()=>[s(l,{id:"mermaid-9",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20U%5B%22%E7%94%A8%E6%88%B7%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20S%5B%22%E6%9C%8D%E5%8A%A1%22%5D%0A%20%20%20%20S%20--%3E%20C%5B%22Redis%3Cbr%2F%3E%E7%83%AD%E6%95%B0%E6%8D%AE%22%5D%0A%20%20%20%20C%20--%20%22%E5%91%BD%E4%B8%AD%22%20--%3E%20U%0A%20%20%20%20C%20--%20%22%E6%9C%AA%E5%91%BD%E4%B8%AD%22%20--%3E%20D%5B%22MySQL%3Cbr%2F%3E%E8%90%BD%E5%BA%93%22%5D%0A%20%20%20%20S%20--%3E%20Q%5B%22MQ%3Cbr%2F%3E%E5%BC%82%E6%AD%A5%E8%A7%A3%E8%80%A6%22%5D%0A%20%20%20%20Q%20--%3E%20W%5B%22%E4%B8%8B%E6%B8%B8%E6%B6%88%E8%B4%B9%22%5D%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[e(" Loading... ",-1)])]),_:1})),t[6]||(t[6]=n('<h2 id="_1-mysql-索引与事务" tabindex="-1">1. MySQL：索引与事务 <a class="header-anchor" href="#_1-mysql-索引与事务" aria-label="Permalink to &quot;1. MySQL：索引与事务&quot;">​</a></h2><p><strong>一句话：读靠 B+ 树索引（防回表），写靠 redo/undo + 锁（保事务），量大靠分片（读写分离、分库分表）。</strong></p><h3 id="_1-1-b-树与索引-常问" tabindex="-1">1.1 B+ 树与索引（常问） <a class="header-anchor" href="#_1-1-b-树与索引-常问" aria-label="Permalink to &quot;1.1 B+ 树与索引（常问）&quot;">​</a></h3><ul><li><strong>结构：</strong> 非叶子只存 key + 指针，扇出大、树矮、磁盘 IO 少；叶子有序链表，范围查询与排序友好。对比：B 树每层都存数据，扇出小树更高；Hash 索引只擅点查；LSM（SSTable）写友好读放大；倒排索引管全文检索；R-tree 管空间索引。</li><li><strong>聚簇 vs 辅助：</strong> 聚簇索引叶子存整行（一般主键组织表）；辅助索引叶子存主键值，查整行要<strong>回表</strong>。<code>select</code> 字段全在二级索引里即<strong>覆盖索引</strong>，免回表。</li><li><strong>常问：怎么避免回表？</strong> 建覆盖索引（含联合索引）、只取必要字段、联合索引注意列顺序、索引下推缩扫描。</li><li><strong>常问：Join 能否用索引？</strong> 能。Index Nested-Loop Join（小表驱动大表），被驱动表 join key 有索引才快；无索引则退化为大量回表/全表扫描。</li><li><strong>哪些列建索引：</strong> <code>where/join/order by/group by</code> 的高选择性字段；忌：频繁更新且选择性差的列、对列做函数/隐式转换（索引失效）、<code>LIKE &#39;%xxx&#39;</code>、OR 散射。<code>varchar</code> 波动大用变长，<code>char</code> 适合短定长。</li><li><strong>NULL 与空串：</strong> NULL 是未知，比较用 <code>IS NULL</code>；<code>count(col)</code> 不统计 NULL；<code>&#39;&#39;</code> 是值。必要字段尽量 <code>NOT NULL</code>。</li></ul><h3 id="_1-2-事务、锁与复制" tabindex="-1">1.2 事务、锁与复制 <a class="header-anchor" href="#_1-2-事务、锁与复制" aria-label="Permalink to &quot;1.2 事务、锁与复制&quot;">​</a></h3><ul><li><strong>ACID 落点：</strong> 原子性靠 undo，持久性靠 redo，隔离性靠锁 + MVCC，一致性靠约束与应用逻辑。</li><li><strong>隔离级别：</strong> READ UNCOMMITTED（脏读）→ READ COMMITTED（防脏读）→ REPEATABLE READ（MySQL 默认，防不可重复读）→ SERIALIZABLE（全串行）。</li><li><strong>InnoDB 锁：</strong> 行锁（Record/Gap/Next-Key，Next-Key 防幻读）、表锁（意向锁）、<code>SELECT ... FOR UPDATE</code> 配事务；锁与事务边界一致，忌长事务。</li><li><strong>主从复制：</strong> 全量建起点 + binlog 增量重放。优点：读扩展、容灾、备份、分析隔离；代价：写仍单点、复制延迟、故障可丢数（看半同步/强一致方案）。读写分离 + 延迟监控是标配。</li><li><strong>binlog 格式（常问）：</strong> statement（记 SQL，省空间但函数/时序易歧义）、row（记行变更，可靠，订阅失效联动就靠它）、mixed（自动切）。主从 + 订阅失效选 row。</li><li><strong>在线 DDL：</strong> 大表加索引/改列用 gh-ost/pt-osc 影子表 + 增量追平，避免锁表。</li><li><strong>SQL 注入：</strong> 参数化（PreparedStatement/ORM 绑定）为主，最小权限与输入校验为辅；拼接 SQL 是根因。</li></ul><h3 id="_1-3-优化三板斧与建模" tabindex="-1">1.3 优化三板斧与建模 <a class="header-anchor" href="#_1-3-优化三板斧与建模" aria-label="Permalink to &quot;1.3 优化三板斧与建模&quot;">​</a></h3><ul><li><strong>表结构：</strong> 类型尽量短、主键与索引合理、忌超宽表；垂直分表拆大字段/低频列，水平分表按 user/order 范围或 hash 拆行（ShardingSphere/MyCAT）。</li><li><strong>SQL：</strong> <code>EXPLAIN</code>（8.0+ 用 <code>EXPLAIN ANALYZE</code>）看路径与行数；忌 <code>select *</code>、filesort、临时表；大表分页用延迟关联/书签式；慢查询日志定位。</li><li><strong>架构：</strong> 读写分离、分库分表、缓存、热点治理、异步化。</li><li><strong>订单表设计（常问案例）：</strong> 主表（状态/金额/地址快照/时间/用户）+ 明细表（sku/数量/单价）；状态机字段 + 流转时间便对账；<code>user_id+created_at</code>、<code>order_no</code> 唯一（幂等对账）；订单号带时间/分片位；冷热分离控单表体量。</li><li><strong>三大范式一句话：</strong> 1NF 列原子，2NF 非主属性依赖完整主键，3NF 消除传递依赖。</li></ul><h2 id="_2-redis-从设计者视角看" tabindex="-1">2. Redis：从设计者视角看 <a class="header-anchor" href="#_2-redis-从设计者视角看" aria-label="Permalink to &quot;2. Redis：从设计者视角看&quot;">​</a></h2><p><strong>一句话：设计顺序是&quot;数据结构定场景 → 单线程架构定实现 → 高可用分片定规模 → 锁与事务定语义 → 应用层治缓存病&quot;——按这个顺序讲，Redis 就通了。</strong></p><h3 id="_2-1-数据结构与场景-常问" tabindex="-1">2.1 数据结构与场景（常问） <a class="header-anchor" href="#_2-1-数据结构与场景-常问" aria-label="Permalink to &quot;2.1 数据结构与场景（常问）&quot;">​</a></h3><ul><li>String（缓存对象/计数器/锁 value）、Hash（对象属性）、List（轻量队列/时间线）、Set（去重/共同好友）、ZSet（排行榜/延时队列，score 做时间戳）、Stream（消费组 + ack 的完整队列）、Bitmaps/HyperLogLog/Geo。</li><li><strong>zset 底层：</strong> 跳表（score 有序，平均 O(log n)）+ 哈希表（member 查 score）。</li><li><strong>场景口诀：</strong> 热数据缓存、计数器、排行榜、去重、分布式锁、限流、轻量队列——复杂语义（消费组/回溯）上 Stream，否则上 MQ。</li></ul><h3 id="_2-2-系统架构-单线程、持久化、高可用、分片、锁、事务" tabindex="-1">2.2 系统架构：单线程、持久化、高可用、分片、锁、事务 <a class="header-anchor" href="#_2-2-系统架构-单线程、持久化、高可用、分片、锁、事务" aria-label="Permalink to &quot;2.2 系统架构：单线程、持久化、高可用、分片、锁、事务&quot;">​</a></h3><ul><li><strong>单线程 + 多路复用：</strong> Reactor 事件循环 + epoll/kqueue，同时扛数万连接，无线程切换开销；命令本身原子，复合操作靠 Lua/事务。</li><li><strong>持久化：</strong> RDB 快照（<code>BGSAVE</code> 子进程，fork/COW 有抖动）、恢复快但可丢数；AOF 追加日志（<code>appendfsync</code> 定策略）、更安全但文件大，靠 rewrite 瘦身。常见 RDB + AOF 组合。</li></ul>',14)),(a(),i(d,null,{default:r(()=>[s(l,{id:"mermaid-162",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20S%5B%22%E5%8D%95%E6%9C%BA%3Cbr%2F%3E%E5%BF%AB%E7%85%A7%E5%8A%A0%E6%97%A5%E5%BF%97%22%5D%20--%3E%20M%5B%22%E4%B8%BB%E4%BB%8E%3Cbr%2F%3E%E8%AF%BB%E5%86%99%E5%88%86%E7%A6%BB%22%5D%0A%20%20%20%20M%20--%3E%20SE%5B%22%E5%93%A8%E5%85%B5%3Cbr%2F%3E%E8%87%AA%E5%8A%A8%E6%95%85%E9%9A%9C%E8%BD%AC%E7%A7%BB%22%5D%0A%20%20%20%20SE%20--%3E%20C%5B%22%E9%9B%86%E7%BE%A4%3Cbr%2F%3E%E6%A7%BD%E5%88%86%E7%89%87%E5%A4%9A%E5%86%99%22%5D%0A"})]),fallback:r(()=>[...t[1]||(t[1]=[e(" Loading... ",-1)])]),_:1})),t[7]||(t[7]=n('<ul><li><strong>高可用演进：</strong> 主从（单写多读）→ Sentinel（监控 + 自动故障转移）→ Cluster（16384 槽分片，多主多写）。扩缩容 = 加节点 + 迁槽 + 客户端更新映射。</li><li><strong>分片：</strong> key → 槽 → 节点，客户端按槽路由；热点用拆 key、读写隔离、就近路由顶。</li><li><strong>分布式锁（常问）：</strong> <code>SET key value NX PX ttl</code> 一步加锁；value 唯一（UUID）防误删；Lua 比对 value 再删；TTL + 续期（watchdog）；强一致场景上更强方案（zk/etcd/RedLock 评估）。</li><li><strong>事务语义：</strong> <code>MULTI/EXEC</code> 只打包顺序执行、无回滚；<code>WATCH</code> 做乐观锁；真原子靠单命令或 Lua。结论：Redis 事务只保&quot;顺序 + 隔离（单线程）&quot;，不保原子回滚。</li><li><strong>一致性深水区（常问）：</strong> 主从异步 → 提升未追上的从，写丢（<code>WAIT</code> 折中或应用幂等兜底）；脑裂双写 → 愈合后旧主数据丢，关键写走 DB 或 quorum；RedLock 有时钟跳变争议，先评估 zk/etcd。</li></ul><h3 id="_2-3-redis-应用-过期、淘汰与治病-常问" tabindex="-1">2.3 Redis 应用：过期、淘汰与治病（常问） <a class="header-anchor" href="#_2-3-redis-应用-过期、淘汰与治病-常问" aria-label="Permalink to &quot;2.3 Redis 应用：过期、淘汰与治病（常问）&quot;">​</a></h3><ul><li><strong>过期删除：</strong> 定时（准实时但贵）+ 惰性（访问时删）+ 定期（周期抽查），三者配合。</li><li><strong>淘汰策略：</strong> volatile 系只动设了 TTL 的 key，allkeys 系全动，noeviction 直接报错。读多写少配 LRU/LFU，时效性强的配 TTL。</li><li><strong>缓存三问题：</strong> 穿透（布隆/空值/参数校验）、击穿（互斥重建、逻辑过期 + 异步重建）、雪崩（TTL 打散、分批预热、限流降级）。</li><li><strong>hotkey 与大 key：</strong> 本地多级缓存、分片 key、异步重建、限流；<code>--bigkeys</code> 扫描发现后拆分。</li><li><strong>性能习惯：</strong> Pipeline 批量降 RTT、Lua 保原子、大 key 拆分、热 key 分散。</li></ul><h2 id="_3-mq-异步与可靠性" tabindex="-1">3. MQ：异步与可靠性 <a class="header-anchor" href="#_3-mq-异步与可靠性" aria-label="Permalink to &quot;3. MQ：异步与可靠性&quot;">​</a></h2><p><strong>一句话：MQ 把&quot;调用&quot;变&quot;投递&quot;——吞吐、解耦、削峰是收益，不丢、不重、有序是代价；代价用 acks + 位移 + 幂等分期付。</strong></p><h3 id="_3-1-三件套选型-常问" tabindex="-1">3.1 三件套选型（常问） <a class="header-anchor" href="#_3-1-三件套选型-常问" aria-label="Permalink to &quot;3.1 三件套选型（常问）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>Kafka</th><th>RabbitMQ</th><th>RocketMQ</th></tr></thead><tbody><tr><td>吞吐</td><td>最高（百万级/s，顺序写 + 零拷贝）</td><td>高（万级/s）</td><td>很高（十万级/s）</td></tr><tr><td>延迟</td><td>毫秒</td><td>微秒</td><td>毫秒</td></tr><tr><td>功能</td><td>偏简</td><td>最丰富（Exchange/DLX/延迟插件）</td><td>事务/顺序/延迟原生</td></tr><tr><td>适用</td><td>日志采集、大数据管道</td><td>企业级应用集成</td><td>金融级可靠投递</td></tr></tbody></table><ul><li><strong>Kafka 可靠三件：</strong> 生产者 acks（0/1/all）、分区多副本 ISR、消费者手动提交位移（<code>__consumer_offsets</code>）。分区是并行单位，rebalance（加减消费者/改分区）会停顿重分配。消费模型是拉（pull），位移自己管。</li><li><strong>RabbitMQ：</strong> Exchange（Direct/Fanout/Topic/Headers）+ Queue + Binding；可靠性靠生产者确认 + 消费 ack + durable + 持久化；TTL + 死信做延迟。推送为主，消费端限流（prefetch）防打爆。</li><li><strong>RocketMQ：</strong> CommitLog 顺序写 + ConsumeQueue 索引；事务消息（半消息 + 回查）；分区顺序（同 Key 同队列）；延迟级别原生。</li></ul><h3 id="_3-2-可靠性四问-常问" tabindex="-1">3.2 可靠性四问（常问） <a class="header-anchor" href="#_3-2-可靠性四问-常问" aria-label="Permalink to &quot;3.2 可靠性四问（常问）&quot;">​</a></h3><ul><li><strong>不丢：</strong> 生产者确认 + 重试 + 本地事务表兜底；Broker 持久化 + 多副本 + 刷盘策略；消费者成功后再提交位移。</li><li><strong>有序：</strong> 单分区/单队列全局有序；同 Key 进同分区；分区内串行消费。</li><li><strong>积压：</strong> 扩消费者、批量消费、跳过非关键位点、优化消费逻辑、监控 lag、先限流生产者。</li><li><strong>幂等：</strong> 业务唯一键去重、消息 ID 去重表、状态机条件更新。工程默认&quot;至少一次 + 幂等&quot;。</li><li><strong>死信：</strong> RabbitMQ 原生 DLX；Kafka 用重试 topic + 死信 topic 模式自建；消费失败超限进死信，人工/定时重放。</li><li><strong>分布式事务选型：</strong> 强一致 2PC；高性能 TCC/Saga；长流程 Saga + 补偿；跨系统异步用事务消息/本地消息表（Outbox：业务与消息同库，定时扫投递）。</li></ul><h2 id="_4-联动-双写一致性与可靠投递" tabindex="-1">4. 联动：双写一致性与可靠投递 <a class="header-anchor" href="#_4-联动-双写一致性与可靠投递" aria-label="Permalink to &quot;4. 联动：双写一致性与可靠投递&quot;">​</a></h2><p><strong>一句话：缓存与 DB 的一致性是&quot;删缓 + 兜底&quot;，业务与 MQ 的一致性是&quot;Outbox + 幂等&quot;——两处都不追求强一致，追求可恢复。</strong></p>',12)),(a(),i(d,null,{default:r(()=>[s(l,{id:"mermaid-363",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20B%5B%22%E4%B8%9A%E5%8A%A1%E4%BA%8B%E5%8A%A1%3Cbr%2F%3E%E5%86%99%20DB%20%E5%8A%A0%20Outbox%22%5D%20--%3E%20M%5B%22MQ%20%E6%8A%95%E9%80%92%22%5D%0A%20%20%20%20M%20--%3E%20C%5B%22%E6%B6%88%E8%B4%B9%E5%B9%82%E7%AD%89%3Cbr%2F%3E%E5%94%AF%E4%B8%80%E9%94%AE%E5%8E%BB%E9%87%8D%22%5D%0A%20%20%20%20C%20--%3E%20A%5B%22%E5%AF%B9%E8%B4%A6%E8%A1%A5%E5%81%BF%3Cbr%2F%3E%E5%AE%9A%E6%97%B6%E6%89%AB%E5%B7%AE%E5%BC%82%22%5D%0A%20%20%20%20A%20--%20%22%E5%A4%B1%E8%B4%A5%E9%87%8D%E6%94%BE%22%20--%3E%20M%0A"})]),fallback:r(()=>[...t[2]||(t[2]=[e(" Loading... ",-1)])]),_:1})),t[8]||(t[8]=n('<ul><li><strong>Cache-Aside：</strong> 读穿（读缓存→未中读 DB→回填）；写先 DB 再删缓存；优化：延时双删、binlog 订阅异步失效、缓存一律加过期兜底。</li><li><strong>可靠投递链：</strong> 本地消息表/Outbox 落库 → 投递 → 消费幂等 → 对账补偿。失败语义先定（全回滚/本批回滚/跳过可查），再写实现。</li><li><strong>热点治理通用：</strong> 热点 key 拆分、singleflight 合并回源、本地缓存、限流隔离——缓存、DB、MQ 三处通用。</li></ul><h2 id="_5-三件套事务一致性对照-常问" tabindex="-1">5. 三件套事务一致性对照（常问） <a class="header-anchor" href="#_5-三件套事务一致性对照-常问" aria-label="Permalink to &quot;5. 三件套事务一致性对照（常问）&quot;">​</a></h2><p><strong>一句话：MySQL 给 ACID，Redis 给单命令原子 + 最终可用，MQ 给至少一次 + 幂等——跨件事务没有银弹，只有 Outbox/Saga/对账三件套。</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>MySQL</th><th>Redis</th><th>MQ</th></tr></thead><tbody><tr><td>事务语义</td><td>ACID + 四档隔离</td><td>MULTI 无回滚 / Lua 原子</td><td>事务消息（RocketMQ）/ 幂等消费</td></tr><tr><td>复制</td><td>半同步可选</td><td>异步（WAIT 折中）</td><td>ISR 多副本 + acks</td></tr><tr><td>分区时</td><td>主从可切（可丢数）</td><td>脑裂可双写（愈合丢数）</td><td>分区内可用，分区间最终一致</td></tr><tr><td>跨件一致</td><td>XA/2PC（重，少用）</td><td>—</td><td>Outbox + Saga + 对账（常用）</td></tr></tbody></table><ul><li><strong>常见问题清单：</strong> 脑裂双写谁赢（新主赢，旧写丢）→ 关键写加唯一约束兜底；时钟跳变（TTL/租约/RedLock 误判）→ fence token 或换 quorum；复制延迟读到旧值 → 关键读走主或版本号校验；消息重投 → 消费端幂等是最后一道门。</li><li><strong>一句话收：</strong> 单件内用其原生机制，跨件一律&quot;至少一次 + 幂等 + 对账&quot;，不手写 2PC。</li></ul><h3 id="存储分层选型-常问" tabindex="-1">存储分层选型（常问） <a class="header-anchor" href="#存储分层选型-常问" aria-label="Permalink to &quot;存储分层选型（常问）&quot;">​</a></h3><ul><li><strong>对象存储（S3/OSS）：</strong> 原始文件（点云/视频/模型），低成本、高吞吐、无限扩展。</li><li><strong>关系库：</strong> 元数据与任务状态，ACID + 复杂查询。</li><li><strong>时序库：</strong> 传感器/指标时序，高效写入 + 时间范围查。</li><li><strong>向量库：</strong> 特征向量相似度检索（维度、距离度量、标量过滤混合查）。</li><li><strong>搜索引擎：</strong> 全文 + 标签聚合。</li><li><strong>索引习惯：</strong> 复合索引（场景/类型/时间）、倒排（标签→ID）、空间索引（R-tree）、常用维度预聚合。</li></ul><h2 id="附-与他篇的边界" tabindex="-1">附：与他篇的边界 <a class="header-anchor" href="#附-与他篇的边界" aria-label="Permalink to &quot;附：与他篇的边界&quot;">​</a></h2><ul><li>缓存更新策略的问答与 Raft 等一致性协议 → 《系统设计笔记》。</li><li>连接池、Pipeline/Lua 批量、慢查询排查命令（<code>EXPLAIN ANALYZE</code>、慢日志）→ 各节已含，不另设篇。</li></ul>',9))])}const S=g(c,[["render",A]]);export{m as __pageData,S as default};
